    /**
     * Handles the initial GET request to the authorization endpoint.
     *
     * Resolves PAR or request-object parameters (redirecting to their reference when consumed now),
     * validates the client, and either resumes an existing session silently or renders the first
     * login step. When prompt=none and no session serves the request, it immediately redirects with an error.
     */
    public function authorize(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $tenant = $args['tenant'];
        $resolved = $this->resolveRequest($request, $tenant);
        if ($resolved->consumedNow) {
            return $this->redirectToReference($tenant, $resolved, $response);
        }
        $flow = $this->buildContext($request, $tenant, $resolved);
        $this->logDebug('OIDC authorize enter', [
            'tenant' => $tenant,
            'clientId' => $flow->clientId,
            'prompt' => $flow->prompt,
            'sessionId' => (string) ($flow->sessionId ?? ''),
            'state' => $flow->state,
            'nonce' => $flow->nonce,
        ]);
        $client = $this->verifyClient($flow->clientId, $tenant, $flow->redirect, $flow->scope);
        $requestError = $this->rejectInvalidRequest($flow, $client, $response);
        if ($requestError !== null) {
            return $requestError;
        }
        $authRequest = $this->buildAuthRequest($flow, $client);
        $sess = $this->sessions->findActiveSession($flow->sessionId ?? '', $flow->issuer);
        $this->logDebug('OIDC authorize session lookup', [
            'tenant' => $tenant,
            'sessionId' => (string) ($flow->sessionId ?? ''),
            'sessionFound' => $sess ? 'true' : 'false',
        ]);
        $decision = $this->sessionPolicy->decide($flow, $sess);
        if ($decision === SessionDecision::Reuse) {
            return $this->cisdPage($request, $response, $flow, $authRequest);
        } elseif ($decision === SessionDecision::LoginRequired) {
            return $this->silentError($flow, 'login_required', $response);
        } else {
            $input = $this->buildStepInput($flow, $request, $authRequest, new ChallengesState(), []);
            try {
                return $this->renderStep(null, null, $input, $response, null, $input->challenges);
            } catch (LoginException $ex) {
                if ($ex->auth->error === AuthenticationResult::ERR_UNKNOW_USER) {
                    return $this->renderNotFound($tenant, $flow->locale, $request, $response);
                }
                throw $ex;
            }
        }
    }

    /**
     * Handles the check-session POST that resumes an authenticated session silently.
     *
     * Verifies the CSRF token (csid), reloads the session, and immediately completes
     * the authorization flow without showing any login UI. If the session has expired, no longer
     * serves the request (SessionSufficiencyPolicy) or the csid is invalid, the user is redirected
     * back to the login form. prompt=consent renders the scope consent step first, and with
     * prompt=none any step that needs the user becomes an error for the client instead.
     *
     * When sessionAuthenticated requires an intermediate step (e.g. terms consent), the step
     * form is rendered WITHOUT clearing the session cookie so subsequent submissions come back
     * here and are dispatched to the correct step handler via runSessionStep().
     */
    public function refresh(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $body = (array) ($request->getParsedBody() ?? []);
        $tenant = $args['tenant'];
        $resolved = $this->resolveRequest($request, $tenant);
        if ($resolved->consumedNow) {
            return $this->redirectToReference($tenant, $resolved, $response);
        }
        $flow = $this->buildContext($request, $tenant, $resolved);
        $this->logDebug('OIDC check-session enter', [
            'tenant' => $tenant,
            'clientId' => $flow->clientId,
            'prompt' => $flow->prompt,
            'sessionId' => (string) ($flow->sessionId ?? ''),
            'hasCsid' => isset($body['csid']) ? 'true' : 'false',
            'state' => $flow->state,
            'nonce' => $flow->nonce,
        ]);
        $client = $this->verifyClient($flow->clientId, $tenant, $flow->redirect, $flow->scope);
        $requestError = $this->rejectInvalidRequest($flow, $client, $response);
        if ($requestError !== null) {
            return $requestError;
        }
        $authRequest = $this->buildAuthRequest($flow, $client);
        $csid = $this->securer->verifyToken($body['csid'] ?? '');
        if ($csid === null) {
            $this->logWarning('OIDC check-session invalid csid', [
                'tenant' => $tenant,
                'sessionId' => (string) ($flow->sessionId ?? ''),
            ]);
            return $this->redirectToLogin($response, $flow, $authRequest);
        }
        $sess = $this->sessions->findActiveSession($flow->sessionId ?? '', $flow->issuer);
        if ($sess && $this->sessionPolicy->decide($flow, $sess) === SessionDecision::Reuse) {
            $this->logDebug('OIDC check-session session loaded', [
                'tenant' => $tenant,
                'sessionId' => (string) ($flow->sessionId ?? ''),
                'sessionUserId' => $sess->userId,
                'sessionClientId' => $sess->clientId,
            ]);
            $challenges = (new ChallengesState())
                ->withUsername($sess->userId)
                ->withMfa($sess->withMfa)
                ->withSession(true);
            $input = $this->buildStepInput($flow, $request, $authRequest, $challenges, $body);
            $step = $body['step'] ?? null;
            if ($step !== null && $step !== '') {
                return $this->runSessionStep($step, $csid, $tenant, $flow, $client, $authRequest, $input, $request, $response);
            }
            try {
                if ($flow->prompts()->has(Prompt::CONSENT)) {
                    throw new LoginException(AuthenticationResult::scopesConsentRequired());
                }
                $auth = $this->authenticator->sessionAuthenticated(
                    $authRequest,
                    $challenges,
                    $tenant,
                    $flow->issuer,
                    $sess->csid,
                    $flow->sessionId ?? '',
                    $flow->state,
                    $flow->nonce
                );
                return $this->completeAuthorization($flow, $auth, $client, $authRequest, $response);
            } catch (LoginException $ex) {
                if ($flow->prompts()->has(Prompt::NONE)) {
                    // The session stays: only this request needed the user.
                    return $this->silentError($flow, self::interactionError($ex->auth), $response);
                }
                // Render the step form (e.g. consent) but keep the session cookie intact so the
                // user's next submission hits this same endpoint with the session still valid.
                $result = $this->executeStep($input, $response, $ex->auth, null, null);
                if ($result->type !== StepResult::TYPE_RENDER || !$result->response) {
                    throw new UnauthorizedException();
                }
                return $result->response;
            }
        } else {
            $this->logWarning('OIDC check-session missing or insufficient session', [
                'tenant' => $tenant,
                'sessionId' => (string) ($flow->sessionId ?? ''),
            ]);
            return $this->redirectToLogin($response, $flow, $authRequest);
        }
    }

    private function runSessionStep(
        string $step,
        string $csid,
        string $tenant,
        OidcFlowContext $flow,
        ClientData $client,
        AuthenticationRequest $authRequest,
        StepInput $input,
        ServerRequestInterface $request,
        ResponseInterface $response
    ): ResponseInterface {
        try {
            $result = $this->executeStep($input, $response, null, $step, $csid);
            if ($result->type === StepResult::TYPE_PROCEED && $result->authResponse && self::consentPending($flow, $step)) {
                // Rendered without clearing the session cookie, like any other session step.
                $result = $this->executeStep($input, $response, AuthenticationResult::scopesConsentRequired(), null, null);
            }
            if ($result->type === StepResult::TYPE_PROCEED && $result->authResponse) {
                return $this->completeAuthorization($flow, $result->authResponse, $client, $authRequest, $response);
            }
            if ($result->type === StepResult::TYPE_RENDER && $result->response) {
                return $result->response;
            }
            throw new UnauthorizedException();
        } catch (LoginException $ex) {
            $isConsentStep = in_array($ex->auth->error, [
                AuthenticationResult::ERR_CONSENT_REQUIRED,
                AuthenticationResult::ERR_SCOPES_CONSENT_REQUIRED,
            ], true);
            if ($isConsentStep) {
                // Consent was stored but the current DB snapshot (REPEATABLE READ) doesn't reflect
                // the write yet. Redirect to GET /authorize so a fresh DB connection picks it up,
                // without prompt and max_age: the user just went through them, so asking again loops.
                $continuation = $flow->continuationParams();
                unset($continuation['max_age']);
                $url = $this->urlBuilder->authorizeUrl($authRequest, $tenant, $flow->state, $flow->nonce, array_filter([
                    'code_challenge' => $flow->codeChallenge,
                    'code_challenge_method' => $flow->codeChallengeMethod,
                ]) + $continuation);
                return $response->withStatus(302)->withHeader('Location', $url);
            }
            return $this->renderSessionError($flow, $ex->auth->error ?? 'access_denied', $ex->getMessage(), $request, $response);
        } catch (UnauthorizedException $ex) {
            return $this->renderSessionError($flow, 'access_denied', $ex->getMessage(), $request, $response);
        }
    }

    #[OA\Post(
        path: '/oauth/openid/{tenant}/authorize',
        summary: 'Authorization Endpoint — form submission',
        description: 'Processes login form submissions (credentials, MFA steps). Not intended for direct API calls; called by the browser during the interactive login flow.',
        tags: ['OIDC'],
        parameters: [
            new OA\Parameter(name: 'tenant', in: 'path', required: true, schema: new OA\Schema(type: 'string')),
        ],
        requestBody: new OA\RequestBody(
            content: new OA\MediaType(
                mediaType: 'application/x-www-form-urlencoded',
                schema: new OA\Schema(properties: [
                    new OA\Property(property: 'step', type: 'string', description: 'Current login step'),
                    new OA\Property(property: 'username', type: 'string'),
                    new OA\Property(property: 'password', type: 'string'),
                    new OA\Property(property: 'csid', type: 'string', description: 'Cross-site ID token'),
                ])
            )
        ),
        responses: [
            new OA\Response(response: 302, description: 'Redirect with authorization code on successful login'),
            new OA\Response(response: 200, description: 'HTML form for next login step or error'),
        ]
    )]
    /**
     * Handles form POST submissions at each step of the interactive login flow.
     *
     * Reads the current step and pre-session cookie, executes the appropriate step handler
     * (credential check, MFA, consent, etc.), and either redirects with an authorization code
     * on success or re-renders the step with an error message on failure. With prompt=consent,
     * a successful step other than the scope consent itself leads to the scope consent step.
     */
    public function formAuthorize(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $body = (array) ($request->getParsedBody() ?? []);
        $tenant = $args['tenant'];
        $resolved = $this->resolveRequest($request, $tenant);
        if ($resolved->consumedNow) {
            return $this->redirectToReference($tenant, $resolved, $response);
        }
        $flow = $this->buildContext($request, $tenant, $resolved);
        $client = $this->verifyClient($flow->clientId, $tenant, $flow->redirect, $flow->scope);
        $requestError = $this->rejectInvalidRequest($flow, $client, $response);
        if ($requestError !== null) {
            return $requestError;
        }
        $clientRequest = $this->buildAuthRequest($flow, $client);
        $state = new ChallengesState();
        if ($flow->preSessionId !== null && $flow->preSessionId !== '') {
            $state = $this->cookies->loadPreSessionChallenges($tenant, $flow->preSessionId);
        }
        $step = $body['step'] ?? null;
        $input = $this->buildStepInput($flow, $request, $clientRequest, $state, $body);
        try {
            // Tengo que sacar la password de fuera
            $csid = null;
            if (isset($body['csid'])) {
                $csid = $this->securer->verifyToken($body['csid']);
                if ($csid === null) {
                    throw new UnauthorizedException('missingin_csid');
                }
            }

            $result = $this->executeStep($input, $response, null, $step, $csid);
            if ($result->type === StepResult::TYPE_PROCEED && $result->authResponse) {
                if (self::consentPending($flow, $step)) {
                    return $this->renderStep(null, AuthenticationResult::scopesConsentRequired(), $input, $response, null, $result->challenges);
                }
                return $this->completeAuthorization($flow, $result->authResponse, $client, $clientRequest, $response);
            }
            if ($result->type === StepResult::TYPE_RENDER && $result->response) {
                $response = $this->cookies->clearSession($result->response, $tenant);
                $cookie = $this->cookies->storePreSession($flow, $result->challenges);
                return $cookie->attach($response);
            }

            throw new UnauthorizedException();
        } catch (LoginException $ex) {
            $isRecoverableStep = in_array($ex->auth->error, [
                AuthenticationResult::ERR_CONSENT_REQUIRED,
                AuthenticationResult::ERR_SCOPES_CONSENT_REQUIRED,
            ], true);
            if ($state->session && !$isRecoverableStep) {
                return $this->renderSessionError($flow, $ex->auth->error ?? 'access_denied', $ex->getMessage(), $request, $response);
            }
            return $this->renderStep($ex->getMessage(), $ex->auth, $input, $response, null, $ex->challenges ?? $state);
        } catch (UnauthorizedException $ex) {
            if ($state->session) {
                return $this->renderSessionError($flow, 'access_denied', $ex->getMessage(), $request, $response);
            }
            return $this->renderStep($ex->getMessage(), null, $input, $response, null, $state);
        }
    }

    /**
     * Returns the error response for a request the client cannot make, once its redirect URI is
     * validated for it, checking in this order:
     * - a missing response_type (invalid_request), one this server does not issue
     *   (unsupported_response_type: implicit is retired) or one not registered for the client
     *   (unauthorized_client, task 033);
     * - an unknown response_mode, or the query for a response with tokens (invalid_request);
     * - an ID token in the front channel without the openid scope or without nonce, which binds
     *   it to this request (invalid_request, task 070);
     * - prompt=none combined with other values, or a max_age that is not a non-negative integer
     *   (invalid_request, task 031);
     * - an audience not registered for the client (invalid_target): only approved audiences reach
     *   the code;
     * - PKCE missing for a client that requires it (public or require-pkce), incomplete (a method
     *   without challenge) or not a valid S256 challenge (invalid_request). The token endpoint
     *   applies the same PKCE policy when the code is redeemed.
     */
    private function rejectInvalidRequest(OidcFlowContext $flow, ClientData $client, ResponseInterface $response): ?ResponseInterface
    {
        $responseType = ResponseType::fromString($flow->responseType);
        $error = match (true) {
            $responseType->isEmpty() => 'invalid_request',
            !$responseType->isSupported() => 'unsupported_response_type',
            !$responseType->isAmong($client->responseTypes) => 'unauthorized_client',
            ResponseMode::resolve($responseType, $flow->requestedResponseMode) === null => 'invalid_request',
            $responseType->has('id_token') && (!ScopeSet::fromString($flow->scope)->has('openid') || $flow->nonce === '') => 'invalid_request',
            !$flow->prompts()->isValid() || !$flow->hasValidMaxAge() => 'invalid_request',
            !$client->allowsAudiences($flow->audiences) => 'invalid_target',
            default => $this->pkceError($flow, $client),
        };
        return $error === null ? null : $this->redirectError($flow, $error, $response);
    }

    /**
     * True when prompt=consent still asks for the scope consent: any step but the scope consent
     * itself has run, whichever endpoint (/authorize or /check-session) it was posted to.
     */
    private static function consentPending(OidcFlowContext $flow, ?string $step): bool
    {
        return $flow->prompts()->has(Prompt::CONSENT) && $step !== StepName::SCOPES_CONSENT->value;
    }

    /**
     * Error of a prompt=none request, returned to the client without touching any cookie: the
     * session may still serve other requests (one without max_age, or an interactive one).
     */
    private function silentError(OidcFlowContext $flow, string $error, ResponseInterface $response): ResponseInterface
    {
        $this->logWarning('OIDC prompt=none error', ['tenant' => $flow->tenant, 'redirect' => $flow->redirect, 'error' => $error]);
        return $this->responses->error($flow, $error, $response);
    }

    /**
     * Error for prompt=none when the session needs the user for a step: consent_required for a
     * consent (terms or scopes), interaction_required for anything else (MFA, new password...).
     */
    private static function interactionError(AuthenticationResult $auth): string
    {
        return in_array($auth->error, [AuthenticationResult::ERR_CONSENT_REQUIRED, AuthenticationResult::ERR_SCOPES_CONSENT_REQUIRED], true)
            ? 'consent_required'
            : 'interaction_required';
    }

    private function pkceError(OidcFlowContext $flow, ClientData $client): ?string
    {
        try {
            $pkce = PkceChallenge::fromRequest($flow->codeChallenge, $flow->codeChallengeMethod);
        } catch (\InvalidArgumentException) {
            return 'invalid_request';
        }
        return $pkce === null && $client->requiresPkce() ? 'invalid_request' : null;
    }

    /**
     * Issues the authorization response, closing the request reference of a PAR or JAR request:
     * a reference that already completed an authorization gets invalid_request instead, and one
     * whose issuance fails stays open for a retry.
     */
    private function completeAuthorization(
        OidcFlowContext $flow,
        PublicLoginAuthResponse $auth,
        ClientData $client,
        AuthenticationRequest $authRequest,
        ResponseInterface $response
    ): ResponseInterface {
        $issued = $this->requestResolver->complete(
            $flow->tenant,
            $flow->requestRef,
            fn (): ResponseInterface => $this->responseBuilder->buildSuccessRedirect($flow, $auth, $client, $authRequest, $response)
        );
        return $issued ?? $this->redirectError($flow, 'invalid_request', $response);
    }

    private function resolveRequest(ServerRequestInterface $request, string $tenant): ResolvedAuthorizationRequest
    {
        return $this->requestResolver->resolve($tenant, $this->context->getIssuer($tenant), $request->getQueryParams());
    }

    /**
     * Sends the browser to /authorize with only the client_id and the signed reference of the
     * PAR or JAR request just consumed, so every following step posts back to that URL.
     */
    private function redirectToReference(string $tenant, ResolvedAuthorizationRequest $resolved, ResponseInterface $response): ResponseInterface
    {
        $url = $this->context->getIssuer($tenant) . '/authorize?' . http_build_query([
            'client_id' => (string) ($resolved->params['client_id'] ?? ''),
            AuthorizationRequestResolver::REFERENCE_PARAM => $resolved->reference,
        ], '', '&', PHP_QUERY_RFC3986);
        return $response->withStatus(302)->withHeader('Location', $url);
    }

    /**
     * The flow context only reads the resolved parameters; the query of a PAR or JAR request is
     * never merged in. Cookies and headers still come from the HTTP request.
     */
    private function buildContext(ServerRequestInterface $request, string $tenant, ResolvedAuthorizationRequest $resolved): OidcFlowContext
    {
        return OidcFlowContext::fromRequest($request->withQueryParams($resolved->params), $tenant, $this->context, $resolved->reference);
    }

    private function buildAuthRequest(OidcFlowContext $flow, ClientData $client): AuthenticationRequest
    {
        return new AuthenticationRequest(
            client: $client,
            scope: $flow->scope,
            redirect: $flow->redirect,
            responseType: $flow->responseType,
            audiences: array_values(array_unique([$flow->clientId, ...$flow->audiences]))
        );
    }

    private function verifyClient(string $clientId, string $tenant, string $redirect, string $scope): ClientData
    {
        $client = $this->clients->publicClientData($clientId, $tenant, $redirect, $scope);
        if (!$client) {
            throw new UnauthorizedException('Client not allowed');
        } else {
            return $client;
        }
    }

    /**
     * Returns an OAuth error to the client in the flow's response mode, with state and iss. Only
     * for a redirect URI already validated for the client (verifyClient).
     */
    private function redirectError(OidcFlowContext $flow, string $error, ResponseInterface $response): ResponseInterface
    {
        $this->logWarning('OIDC redirect error', [
            'tenant' => $flow->tenant,
            'redirect' => $flow->redirect,
            'error' => $error,
        ]);
        return $this->cookies->clearSession($this->responses->error($flow, $error, $response), $flow->tenant);
    }

    private function renderStep(?string $message, ?AuthenticationResult $error, StepInput $input, ResponseInterface $response, ?string $stepOverride, ?ChallengesState $challengesOverride): ResponseInterface
    {
        $error = $error === null && $message !== null && $message !== ''
            ? new AuthenticationResult(valid: false, errorMessage: $message)
            : $error;
        $step = $error ? null : ($stepOverride ?? ($input->request->getQueryParams()['step'] ?? null));
        if ($challengesOverride !== null) {
            $input = new StepInput(
                context: $input->context,
                authRequest: $input->authRequest,
                challenges: $challengesOverride,
                body: $input->body,
                request: $input->request
            );
        }
        $result = $this->executeStep($input, $response, $error, $step, null);
        if ($result->type !== StepResult::TYPE_RENDER || !$result->response) {
            throw new UnauthorizedException();
        }
        $response = $this->cookies->clearSession($result->response, $input->context->tenant);
        $cookie = $this->cookies->storePreSession($input->context, $result->challenges);
        return $cookie->attach($response);
    }

    private function executeStep(
        StepInput $input,
        ResponseInterface $response,
        ?AuthenticationResult $error,
        ?string $step,
        ?string $csid
    ): StepResult {
        $result = $this->router->run($input, $response, $error, $step, $csid);
        if (!$result) {
            throw new UnauthorizedException();
        }
        return $result;
    }

    private function buildStepInput(
        OidcFlowContext $flow,
        ServerRequestInterface $request,
        AuthenticationRequest $authRequest,
        ChallengesState $state,
        ?array $body
    ): StepInput {
        return new StepInput(
            context: $flow,
            authRequest: $authRequest,
            challenges: $state,
            body: $body ?? [],
            request: $request
        );
    }

    private function redirectToLogin(
        ResponseInterface $response,
        OidcFlowContext $flow,
        AuthenticationRequest $authRequest
    ): ResponseInterface {
        $this->logDebug('OIDC redirectToLogin', [
            'tenant' => $flow->tenant,
            'clientId' => $flow->clientId,
            'prompt' => $flow->prompt,
            'sessionId' => (string) ($flow->sessionId ?? ''),
        ]);
        if ($flow->prompts()->has(Prompt::NONE)) {
            return $this->silentError($flow, 'login_required', $response);
        } else {
            $url = $this->urlBuilder->authorizeUrl(
                $authRequest,
                $flow->tenant,
                $flow->state,
                $flow->nonce,
                ['prompt' => $flow->prompt] + $flow->continuationParams()
            );
            $response = $response->withStatus(302)->withHeader('Location', $url);
            return $this->cookies->clearSession($response, $flow->tenant);
        }
    }

    private function renderNotFound(string $tenant, string $locale, RequestInterface $request, ResponseInterface $response): ResponseInterface
    {
        $this->logWarning('OIDC tenant not found', ['tenant' => $tenant]);
        $translator = $this->translator($locale);
        $response->getBody()->write(
            $this->decorator->getFullPage(
                $request,
                $translator->get('authorize.not-found.title'),
                '<div class="error-page"><h1>404</h1><p>' . $translator->get('authorize.not-found.help') . '</p></div>',
                $locale,
                'index',
                null
            )
        );
        return $response->withStatus(404);
    }

    private function renderSessionError(
        OidcFlowContext $flow,
        string $errorCode,
        string $errorMessage,
        RequestInterface $request,
        ResponseInterface $response
    ): ResponseInterface {
        $this->logWarning('OIDC session error page', ['tenant' => $flow->tenant, 'error' => $errorCode]);
        $safeMessage = htmlspecialchars($errorMessage, ENT_QUOTES);
        $safeCode = htmlspecialchars($errorCode, ENT_QUOTES);
        $translator = $this->translator($flow->locale);
        $title = $translator->get('authorize.error.title');
        $back = $this->responses->errorButton($flow, $errorCode, $translator->get('authorize.error.back'));
        $response->getBody()->write(
            $this->decorator->getFullPage(
                $request,
                $title,
                <<<HTML
                    <div class="error-page">
                        <h1>{$title}</h1>
                        <p><strong>{$safeCode}</strong></p>
                        <p>{$safeMessage}</p>
                        {$back}
                    </div>
                HTML,
                $flow->locale,
                'index',
                $flow->tenant
            )
        );
        return $response->withStatus(400);
    }

    /**
     * Login catalogue in the UI language negotiated for the request (UiLocale).
     */
    private function translator(string $locale): MessageCatalogue
    {
        return $this->messages->messages('forms', $locale, __DIR__ . '/../Translations');
    }

    private function cisdPage(
        RequestInterface $request,
        ResponseInterface $response,
        OidcFlowContext $flow,
        AuthenticationRequest $authRequest
    ): ResponseInterface {
        $js = $this->securer->configureScripts([
            $this->securer->addSignAndSend("sign", "refresh"),
        ]);
        $url = $this->urlBuilder->checkSessionUrl(
            $authRequest,
            $flow->tenant,
            $flow->state,
            $flow->nonce,
            [
                'prompt' => $flow->prompt,
                'code_challenge' => $flow->codeChallenge,
                'code_challenge_method' => $flow->codeChallengeMethod,
            ] + $flow->continuationParams()
        );
        $title = $this->translator($flow->locale)->get('authorize.check-session.title');
        $response->getBody()->write($this->decorator->getFullPage($request, $title, $js . "<h1>{$title}</h1>"
            . "<form id=\"refresh\" action=\"".$url."\" method=\"POST\">"
            . "<input type=\"hidden\" name=\"csid\" id=\"sign\" />"
            . "<input type=\"submit\" style=\"display:none\" />"
            . "</form>", $flow->locale, 'index', $flow->tenant));
        return $response;
    }
}
